// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 timestamp, uint256 blockNumber) public {
        // Bound inputs to realistic values
        vm.assume(blockNumber < 2**64);

        // Set block timestamp and number
        vm.warp(timestamp);
        vm.roll(blockNumber);

        // Make two calls with identical block.timestamp to trigger the bug
        // First call succeeds and sets pastBlockTime = timestamp
        vm.deal(address(this), 10 ether);
        (bool success1, ) = address(c).call{value: 10 ether}("");

        // Second call with same timestamp should revert in reference,
        // but may succeed in mutant
        vm.deal(address(this), 10 ether);
        (bool success2, ) = address(c).call{value: 10 ether}("");

        // The property: after two calls with same timestamp,
        // the second call must revert
        assertTrue(!success2);
    }
}

